(function(root){'use strict';
const catalog=[{id:'template-trend',title:'趋势策略研究模板',kind:'策略学习模板',concept:'样本外验证',requires:[],status:'active',access:'local',fee:'免费',description:'定义趋势信号 → 划分训练/验证样本 → 加入换手费用 → 记录不同市场状态的表现。仅用于模拟研究。'},{id:'template-value',title:'价值假设研究模板',kind:'策略学习模板',concept:'未来数据泄漏',requires:[],status:'active',access:'local',fee:'免费',description:'明确估值尺度 → 核对发布时间 → 分组检验 → 检查行业偏差与价值陷阱。仅用于模拟研究。'},{id:'template-defense',title:'低波动配置实验',kind:'策略学习模板',concept:'资金占用',requires:[],status:'active',access:'local',fee:'免费',description:'定义波动窗口 → 设置预算与集中度 → 观察回撤和费用 → 与简单基准比较。低波动不等于保本。'},{id:'course-cost',title:'净收益与交易成本',kind:'微课程',concept:'交易成本',requires:[],status:'active',access:'local',fee:'免费',description:'区分毛结果、费用、净结果，用小实验核对账本。'}];
function validate(result,state){if(result.mode!=='mock'&&result.mode!=='ai')throw Error('画像来源无效');const ids=new Set(state.evidence.map(e=>e.id));if(!Array.isArray(result.labels)||result.labels.length>12)throw Error('标签数量无效');for(const l of result.labels){if(!/^[a-z][a-z0-9_-]{0,39}$/.test(l.id)||!l.text||!l.context||!Array.isArray(l.evidence_ids)||!l.evidence_ids.length||l.evidence_ids.some(x=>!ids.has(x)))throw Error('画像缺少有效证据');}for(const r of result.recommendations)if(!catalog.some(c=>c.id===r.resource_id&&c.status==='active'&&c.access==='local'))throw Error('推荐目录无效');return result;}
function analyze(s){const labels=[];const add=(id,text,ev,context)=>{if(ev.length)labels.push({id,text,evidence_ids:ev.map(e=>e.id),context,status:s.analystCorrections?.[id]?.status||'candidate',edited:s.analystCorrections?.[id]?.text||null});};add('explanation','习惯解释模拟决策的理由',s.evidence.filter(e=>e.dimension==='ai'),'来自本局主动填写的决策理由，不等于真实投资能力');for(const [id,text] of [['risk','关注模拟风险边界'],['tech','关注数据与验证依据'],['finance','关注资金占用和费用']]){const ev=s.evidence.filter(e=>e.dimension===id);add(id,text,ev,'本局 '+new Set(ev.map(e=>e.eventId)).size+' 个场景；其中 '+ev.filter(e=>e.prompted).length+' 次来自界面提示，'+ev.filter(e=>!e.prompted).length+' 次自主提问');}add('city','尝试用因子材料构建策略区域',s.evidence.filter(e=>e.dimension==='city'),'合成行情下的城区配置记录；只代表探索行为');add('learning','使用微课堂核对概念',s.evidence.filter(e=>e.dimension==='knowledge'),'学习后的练习证据；未测试真实交易或跨任务迁移能力');const active=labels.filter(l=>l.status!=='rejected'&&l.status!=='roleplay'),district=s.city?.districts?.[0];const resource=district?'template-'+district.id:s.goal==='编程研究'?'template-value':'template-trend';const recommendations=[{resource_id:resource,reason:district?'你在城市中明确配置了这一类区域；下一步可以把模拟构造改写为可验证研究假设。':'你明确选择了「'+s.goal+'」，这个模板可帮助你形成可检验规则。'},{resource_id:'course-cost',reason:s.lessons.includes('交易成本')?'你已进入成本课堂，可用练习继续核对净收益。':'本局费用影响结算，可先补齐成本概念。'}];return validate({mode:'mock',version:1,labels,narrative:active.length?`${s.name}总，这一局留下了 ${s.evidence.length} 条过程证据。你的探索目标是「${s.goal}」。可观察到：${active.map(l=>l.edited||l.text).join('、')}。这些记录只描述本次模拟情境；角色提示后的行为与自主决定已分开。尚无足够证据判断真实风险承受能力、稳定交易风格或盈利能力。`:'这一局还没有足够且被你认可的过程证据，交易画像暂为未知。你仍然可以根据自述目标选择学习路径。',recommendations},s);}
root.ProfileAnalyst={catalog,validate,analyze};if(typeof module!=='undefined')module.exports=root.ProfileAnalyst;
})(typeof window==='undefined'?globalThis:window);
